import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Performance Meeting 2020-09-24","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-09-24","date":"2020-09-24T00:00:00.000Z","updated":"2020-09-25T00:00:00.000Z","tags":["Ceph","RocksDB","Performance Optimization","Object Storage","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-09-24.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-09-24.md","lastUpdated":1780460162000}'),i={name:"posts/2020/Ceph_Performance_Meeting_2020-09-24.md"};function r(s,e,n,c,u,h){return t(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>新拉取请求 (Pull Requests)</strong>: <ul><li>Adam Core提交了一个PR，旨在为每个列族提供独立的RocksDB块缓存。</li><li>另一个PR是关于并发检索设备数据的软卷，标记为性能相关。</li></ul></li><li><strong>更新拉取请求</strong>: <ul><li>动态级别在RocksDB中的实现。</li><li>RGW中的D3N缓存更改，经过QA测试，但可能需要进一步工作。</li></ul></li><li><strong>优化放置组 (Placement Group) 移除</strong>: <ul><li>Mark提到一个优化放置组移除的PR，包含修复，如重用集合列表的下一个位置和立即从缓存中移除已删除的节点。</li></ul></li><li><strong>RocksDB性能分析</strong>: <ul><li>讨论了RocksDB的写前日志 (write ahead log) 和内存表 (mem table) 的行为，特别是关于如何处理PG日志和对象节点的同步问题。</li></ul></li><li><strong>未来行动计划</strong>: <ul><li>Gabi将继续研究RocksDB代码，探索是否可以实现一个可丢弃的内存表。</li><li>重新评估和测试移除PG日志对性能的影响。</li></ul></li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>RocksDB的缓存和写前日志行为</strong>: 讨论了如何优化RocksDB的缓存和写前日志，以减少IOPS和延迟。</li><li><strong>PG日志的处理</strong>: 探讨了PG日志的存储和处理方式，以及如何在不牺牲一致性的前提下提高性能。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>继续研究和优化RocksDB的使用</strong>: Gabi将继续深入研究RocksDB的内部机制，特别是内存表和写前日志的处理。</li><li><strong>重新测试PG日志的影响</strong>: 计划重新运行移除PG日志的实验，以评估当前代码的性能影响。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>Gabi的研究工作</strong>: Gabi将在接下来的几天内继续研究RocksDB，特别是探索创建一个可丢弃的内存表的可能性。</li><li><strong>性能测试</strong>: 重新进行性能测试，特别是移除PG日志的实验，以评估当前代码的性能表现。</li><li><strong>会议跟进</strong>: 下次会议将讨论Gabi的研究进展和性能测试的结果。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议主要讨论了RocksDB的优化和PG日志的处理。会议确定了Gabi将继续深入研究RocksDB的内部机制，并计划重新进行性能测试以评估移除PG日志的影响。会议还提到了未来可能的改进方向，包括优化内存表和写前日志的处理。</p>',11)])])}const _=a(i,[["render",r]]);export{g as __pageData,_ as default};
